import 'package:flutter/material.dart';

void main() {
  runApp(VisualWidgetsDemo());
}

class VisualWidgetsDemo extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text('Visual Widgets Demo')),
        body: SingleChildScrollView(
          padding: EdgeInsets.all(20),
          child: Column(
            children: [
              // TEXT WIDGET
              // Displays a string of text with single style
              // Properties: style, textAlign, overflow, maxLines
              Text(
                'Hello Flutter Developers!',
                style: TextStyle(
                  fontSize: 24,
                  fontWeight: FontWeight.bold,
                  color: Colors.blue,
                ),
              ),
              SizedBox(height: 20),

              // IMAGE WIDGET
              // Displays an image from various sources (asset, network, file, memory)
              // Properties: fit, width, height, alignment
              Image.network(
                'https://flutter.dev/images/flutter-logo-sharing.png',
                height: 100,
                fit: BoxFit.contain,
              ),
              SizedBox(height: 20),

              // ICON WIDGET
              // Displays a Material Design icon
              // Uses Icons class with hundreds of predefined icons
              // Properties: size, color
              Row(
                mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                children: [
                  Icon(Icons.favorite, color: Colors.red, size: 40),
                  Icon(Icons.star, color: Colors.amber, size: 40),
                  Icon(Icons.thumb_up, color: Colors.blue, size: 40),
                ],
              ),
              SizedBox(height: 20),

              // CIRCLEAVATAR WIDGET
              // Circular widget that represents a user
              // Can contain a child, background image, or just a background color
              // Properties: radius, backgroundColor, backgroundImage
              CircleAvatar(
                radius: 50,
                backgroundColor: Colors.blue.shade100,
                backgroundImage: NetworkImage(
                  'https://randomuser.me/api/portraits/women/44.jpg',
                ),
                child: Text('Profile', style: TextStyle(color: Colors.black)),
              ),
              SizedBox(height: 20),

              // DIVIDER WIDGET
              // A thin horizontal line, with padding on either side
              // Often used to separate content
              // Properties: color, height, thickness, indent, endIndent
              Column(
                children: [
                  Text('Section 1'),
                  Divider(
                    color: Colors.grey,
                    thickness: 1,
                    height: 30,
                    indent: 20,
                    endIndent: 20,
                  ),
                  Text('Section 2'),
                ],
              ),
              SizedBox(height: 20),

              // LINEARPROGRESSINDICATOR WIDGET
              // Shows progress along a line (indeterminate or determinate)
              // Properties: value, backgroundColor, valueColor
              Column(
                children: [
                  Text('Downloading...'),
                  SizedBox(height: 10),
                  LinearProgressIndicator(
                    value: 0.7, // 70% complete (null for indeterminate)
                    backgroundColor: Colors.grey.shade200,
                    valueColor: AlwaysStoppedAnimation<Color>(Colors.green),
                    minHeight: 10,
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

