import 'package:flutter/material.dart';

void main() => runApp(InteractiveWidgetsDemo());

class InteractiveWidgetsDemo extends StatefulWidget {
	@override
	_InteractiveWidgetsDemoState createState() => _InteractiveWidgetsDemoState();
}

class _InteractiveWidgetsDemoState extends State<InteractiveWidgetsDemo> {
	bool _isChecked = false;
	bool _isSwitched = false;
	double _sliderValue = 50;
	String _textFieldValue = '';

	@override
	Widget build(BuildContext context) {
		return MaterialApp(
			home: Scaffold(
				appBar: AppBar(title: Text('Interactive Widgets')),
				body: SingleChildScrollView(
					padding: EdgeInsets.all(20),
					child: Column(
						children: [
							// TEXTFIELD - Text input field
							TextField(
								onChanged: (value) => setState(() => _textFieldValue = value),
								decoration: InputDecoration(labelText: 'Type something', border: OutlineInputBorder()),
							),
							SizedBox(height: 20),
							// ELEVATEDBUTTON - Material Design raised button
							ElevatedButton(
								onPressed: () => print('Button pressed!'),
								child: Text('Click Me'),
							),
							SizedBox(height: 20),
							// GESTUREDETECTOR - Detects taps, drags, etc.
							GestureDetector(
								onTap: () => print('Box tapped!'),
								onDoubleTap: () => print('Double tapped!'),
								child: Container(
									width: 100,
									height: 100,
									color: Colors.blue,
									child: Center(child: Text('Tap Me', style: TextStyle(color: Colors.white))),
							),
							SizedBox(height: 20),
							// CHECKBOX - Toggleable checkbox
							Row(children: [
								Checkbox(
									value: _isChecked,
									onChanged: (value) => setState(() => _isChecked = value!),
								),
								Text('I agree to terms')
							]),
							SizedBox(height: 20),
							// SLIDER - Material Design slider
							Column(children: [
								Text('Value: ${_sliderValue.round()}'),
								Slider(
									value: _sliderValue,
									min: 0,
									max: 100,
									onChanged: (value) => setState(() => _sliderValue = value),
								)
							]),
							SizedBox(height: 20),
							// SWITCH - Toggle switch
							Row(children: [
								Switch(
									value: _isSwitched,
									onChanged: (value) => setState(() => _isSwitched = value),
								),
								Text('Enable Feature')
							]),
							SizedBox(height: 20),
							// DRAGGABLE - Makes widgets draggable
							Draggable<int>(
								data: 10,
								child: Container(
									width: 100,
									height: 100,
									color: Colors.green,
									child: Center(child: Text('Drag Me', style: TextStyle(color: Colors.white))),
								),
								feedback: Container(
									width: 100,
									height: 100,
									color: Colors.green.withOpacity(0.5),
									child: Center(child: Text('Dragging', style: TextStyle(color: Colors.white))),
								),
								childWhenDragging: Container(
									width: 100,
									height: 100,
									color: Colors.grey,
								),
							)
						]))));
	}
}

